68	export default function App() {
69	  // `?demo=1` is fixed for the page lifetime and uses its own storage key.
70	  const [demoMode] = useState(isDemoMode);
71	  const storageKey = demoMode ? STORAGE_KEYS.demo : STORAGE_KEYS.app;
72	  const [boot] = useState(() => {
73	    const loaded = loadPrototype(browserStorage(), storageKey);
74	    return { data: loaded.data || createSeedData(), issue: loaded.issue };
75	  });
76	  const [storageIssue, setStorageIssue] = useState<StorageIssue | null>(boot.issue || null);
77	  // Unreadable saved data is kept untouched until the user retries or resets.
78	  const [autosave, setAutosave] = useState(boot.issue !== 'corrupt' && boot.issue !== 'version');
79	
80	  // Navigation state
81	  const [activeTab, setActiveTab] = useState<NavTab>(() => NAV_TABS.includes(boot.data.ui.activeTab as NavTab) ? boot.data.ui.activeTab as NavTab : 'home');
82	
83	  // User Auth state (Supabase Auth 연동, 체험 모드에서는 예시 계정 저장소)
84	  const [users, setUsers] = useState<CurrentUser[]>(boot.data.users);
85	  const [currentUser, setCurrentUser] = useState<CurrentUser | null>(() =>
86	    demoMode ? boot.data.users.find(user => user.id === boot.data.activeUserId) || null : null);
87	  const [demoSettings, setDemoSettings] = useState<DemoSettings>(boot.data.demo);
88	  const [favorites, setFavorites] = useState<FavoriteFriend[]>(boot.data.favorites);
89	  const [invitations, setInvitations] = useState<Invitation[]>(boot.data.invitations);
90	  const [completions, setCompletions] = useState<CompletionConfirmation[]>(boot.data.completions);
91	  const [appointmentReviews, setAppointmentReviews] = useState<AppointmentReview[]>(boot.data.appointmentReviews);
92	  const [notificationSettings, setNotificationSettings] = useState<NotificationSettings[]>(boot.data.notificationSettings);
93	  const [blocks, setBlocks] = useState<BlockRelation[]>(boot.data.blocks);
94	  /** Current prototype time: real clock in service mode, shifted clock in the demo. */
95	  const clock = () => demoNow(demoMode ? demoSettings.timeOffsetMs : 0);
96	
97	  useEffect(() => {
98	    if (demoMode && currentUser) setUsers(prev => prev.some(user => user.id === currentUser.id)
99	      ? prev.map(user => user.id === currentUser.id ? currentUser : user)
100	      : [...prev, currentUser]);
101	  }, [currentUser]);
102	
103	  useEffect(() => {
104	    // Demo isolation: no Supabase session restore or auth listener.
105	    if (demoMode) return;
106	    // 1. 초기 세션 확인
107	    supabase.auth.getSession().then(({ data: { session } }) => {
108	      if (session?.user) {
109	        const meta = session.user.user_metadata || {};
110	        const name = meta.realName || '유미당 회원';
111	        const masked = meta.maskedName || maskRealName(name);
112	        setCurrentUser({
113	          id: session.user.id,
114	          isLoggedIn: true,
115	          email: session.user.email,
116	          phone: session.user.phone || '010-0000-0000',
117	          realName: name,
118	          maskedName: masked,
119	          nickname: masked,
120	          gender: meta.gender || 'female',
121	          ageGroup: meta.ageGroup || '20대',
122	          neighborhood: meta.neighborhood || '서울 강남구 역삼동',
123	          sugarContent: NEW_USER_SUGAR,
124	          isPhoneVerified: false,
125	          isKycVerified: false,
126	          avatar: meta.avatar || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80',
127	          bio: meta.bio || '유미당과 함께하는 따뜻한 동행입니다.',
128	          joinedAt: '2026.09',
129	        });
130	      }
131	    });
132	
133	    // 2. Auth 상태 변화 리스너
134	    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
135	      if (session?.user) {
136	        const meta = session.user.user_metadata || {};
137	        const name = meta.realName || '유미당 회원';
138	        const masked = meta.maskedName || maskRealName(name);
139	        setCurrentUser({
140	          id: session.user.id,
141	          isLoggedIn: true,
142	          email: session.user.email,
143	          phone: session.user.phone || '010-0000-0000',
144	          realName: name,
145	          maskedName: masked,
146	          nickname: masked,
147	          gender: meta.gender || 'female',
148	          ageGroup: meta.ageGroup || '20대',
149	          neighborhood: meta.neighborhood || '서울 강남구 역삼동',
150	          sugarContent: NEW_USER_SUGAR,
151	          isPhoneVerified: false,
152	          isKycVerified: false,
153	          avatar: meta.avatar || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80',
154	          bio: meta.bio || '유미당과 함께하는 따뜻한 동행입니다.',
155	          joinedAt: '2026.09',
156	        });
157	      } else {
158	        setCurrentUser(null);
159	      }
160	    });
161	
162	    return () => subscription.unsubscribe();
163	  }, []);
164	
165	  // Modal states
166	  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
167	  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
168	  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
169	  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
170	  const [isKycModalOpen, setIsKycModalOpen] = useState(false);
171	  const [selectedEvent, setSelectedEvent] = useState<EventBannerItem | null>(null);
172	  const [selectedCategory, setSelectedCategory] = useState<CategoryItem | null>(null);
173	
174	  // Phase 2: Post Detail & Editing states
175	  const [selectedPostForDetail, setSelectedPostForDetail] = useState<MeetupPost | null>(null);
176	  const [editingPost, setEditingPost] = useState<MeetupPost | null>(null);
177	
178	  // Phase 3: 1:1 Matching Requests & Modals
179	  const [isJoinRequestModalOpen, setIsJoinRequestModalOpen] = useState(false);
180	  const [selectedPostForJoin, setSelectedPostForJoin] = useState<MeetupPost | null>(null);
181	  const [requestTab, setRequestTab] = useState<RequestTab>('sent');
182	  const [isEventsOpen, setIsEventsOpen] = useState(false);
183	  const [now, setNow] = useState(clock);
184	  useEffect(() => {
185	    setNow(clock());
186	    const timer = setInterval(() => setNow(clock()), 60_000);
187	    return () => clearInterval(timer);
188	  }, [demoSettings.timeOffsetMs]);
189	  const today = koreaDateParts(now);
190	  const eventBanners = sampleEventsForMonth(today.year, today.month);
191	
192	  // Phase 4: Safety, Voice Call & Emergency Report states
193	  const [isSafetyRulesOpen, setIsSafetyRulesOpen] = useState(false);
194	  const [isVoiceCallOpen, setIsVoiceCallOpen] = useState(false);
195	  const [isReportOpen, setIsReportOpen] = useState(false);
196	
197	  // Phase 5: Mutual Blind Review & Sugar Settling states
198	  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
199	  const [reviewAppointmentId, setReviewAppointmentId] = useState<string | null>(null);
200	  const [submittedReviews, setSubmittedReviews] = useState<Record<string, { rating: number; badges: string[]; comment: string }>>({});
201	  const submissionLocks = useRef(new Set<string>());
202	  const settlementLocks = useRef(new Set<string>());
203	
204	  // UI 뒤로가기/닫기 이벤트 및 체류시간 실시간 추적 (Supabase 정규화 테이블 ui_back_events)
205	  const modalOpenTimes = useRef<Record<string, number>>({});
206	
207	  useEffect(() => {
208	    if (selectedPostForDetail) {
209	      modalOpenTimes.current['POST_DETAIL'] = Date.now();
210	      trackFunnelEvent({
211	        step: 'POST_DETAIL_VIEW',
212	        targetPostId: selectedPostForDetail.id,
213	        pageKey: 'POST_DETAIL',
214	      });
215	    } else if (modalOpenTimes.current['POST_DETAIL']) {
216	      const durationMs = Date.now() - modalOpenTimes.current['POST_DETAIL'];
217	      delete modalOpenTimes.current['POST_DETAIL'];
218	      trackBackEvent({ pageKey: 'POST_DETAIL', actionType: 'close', durationMs });
219	    }
220	  }, [selectedPostForDetail]);
221	
222	  useEffect(() => {
223	    if (selectedCategory) {
224	      modalOpenTimes.current['CATEGORY_DETAIL'] = Date.now();
225	    } else if (modalOpenTimes.current['CATEGORY_DETAIL']) {
226	      const durationMs = Date.now() - modalOpenTimes.current['CATEGORY_DETAIL'];
227	      delete modalOpenTimes.current['CATEGORY_DETAIL'];
228	      trackBackEvent({ pageKey: 'CATEGORY_DETAIL', actionType: 'close', durationMs });
229	    }
230	  }, [selectedCategory]);
231	
232	  useEffect(() => {
233	    if (selectedEvent) {
234	      modalOpenTimes.current['EVENT_DETAIL'] = Date.now();
235	    } else if (modalOpenTimes.current['EVENT_DETAIL']) {
236	      const durationMs = Date.now() - modalOpenTimes.current['EVENT_DETAIL'];
237	      delete modalOpenTimes.current['EVENT_DETAIL'];
238	      trackBackEvent({ pageKey: 'EVENT_DETAIL', actionType: 'close', durationMs });
239	    }
240	  }, [selectedEvent]);
241	
242	  useEffect(() => {
243	    if (isCreateModalOpen) {
244	      modalOpenTimes.current['CREATE_MEETUP'] = Date.now();
245	    } else if (modalOpenTimes.current['CREATE_MEETUP']) {
246	      const durationMs = Date.now() - modalOpenTimes.current['CREATE_MEETUP'];
247	      delete modalOpenTimes.current['CREATE_MEETUP'];
248	      trackBackEvent({ pageKey: 'CREATE_MEETUP', actionType: 'close', durationMs });
249	    }
250	  }, [isCreateModalOpen]);
251	
252	  useEffect(() => {
253	    if (isAuthModalOpen) {
254	      modalOpenTimes.current['AUTH'] = Date.now();
255	    } else if (modalOpenTimes.current['AUTH']) {
256	      const durationMs = Date.now() - modalOpenTimes.current['AUTH'];
257	      delete modalOpenTimes.current['AUTH'];
258	      trackBackEvent({ pageKey: 'AUTH', actionType: 'close', durationMs });
259	    }
260	  }, [isAuthModalOpen]);
261	
262	  useEffect(() => {
263	    if (isDashboardOpen) {
264	      modalOpenTimes.current['DASHBOARD'] = Date.now();
265	    } else if (modalOpenTimes.current['DASHBOARD']) {
266	      const durationMs = Date.now() - modalOpenTimes.current['DASHBOARD'];
267	      delete modalOpenTimes.current['DASHBOARD'];
268	      trackBackEvent({ pageKey: 'DASHBOARD', actionType: 'close', durationMs });
269	    }
270	  }, [isDashboardOpen]);
271	
272	  useEffect(() => {
273	    if (isJoinRequestModalOpen) {
274	      modalOpenTimes.current['JOIN_REQUEST'] = Date.now();
275	    } else if (modalOpenTimes.current['JOIN_REQUEST']) {
276	      const durationMs = Date.now() - modalOpenTimes.current['JOIN_REQUEST'];
277	      delete modalOpenTimes.current['JOIN_REQUEST'];
278	      trackBackEvent({ pageKey: 'JOIN_REQUEST', actionType: 'close', durationMs });
279	    }
280	  }, [isJoinRequestModalOpen]);
281	
282	  const [reviews, setReviews] = useState<ReviewItem[]>(boot.data.reviews);
283	
284	  // Phase 6: Pro Paid Companion & Escrow States
285	  const [isEscrowModalOpen, setIsEscrowModalOpen] = useState(false);
286	  const [selectedProPostForEscrow, setSelectedProPostForEscrow] = useState<MeetupPost | null>(null);
287	  const [escrowPayments] = useState<EscrowPayment[]>([
288	    {
289	      id: 'escrow-init-1',
290	      postId: 'post-6',
291	      postTitle: '[PRO] 성수동 감성 골목 인생샷 스냅 촬영 1:1 동행 📸',
292	      hostName: '박*준 (포토그래퍼)',
293	      requesterName: '조*미',
294	      hourlyRate: 30000,
295	      totalHours: 2,
296	      totalAmount: 60000,
297	      status: 'held',
298	      paidAt: '어제',
299	      paymentMethod: 'kakaopay',
300	    },
301	  ]);
302	
303	  const [joinRequests, setJoinRequests] = useState<JoinRequest[]>(boot.data.requests);
304	
305	  // App data states
306	  const [appointments, setAppointments] = useState<Appointment[]>(boot.data.appointments);
307	  const [activeAppointmentId, setActiveAppointmentId] = useState(boot.data.appointments[0]?.id || '');
308	  const appointment = appointments.find(item => item.id === activeAppointmentId) || appointments[0];
309	  const reviewAppointment = appointments.find(item => item.id === reviewAppointmentId) || appointment;
310	  const reviewKey = (id: string) => `${currentUser?.id}:${id}`;
311	  useEffect(() => {
312	    const delay = Math.min(...appointments.map(item => Date.parse(item.endsAt || '') - clock().getTime()).filter(value => value > 0));
313	    if (!Number.isFinite(delay)) return;
314	    const timer = setTimeout(() => setNow(clock()), Math.min(delay, 2_147_483_647));
315	    return () => clearTimeout(timer);
316	  }, [appointments, now]);
317	  const setAppointment = (next: Appointment | ((previous: Appointment) => Appointment)) => {
318	    if (typeof next === 'function') {
319	      setAppointments(previous => previous.map(item => item.id === activeAppointmentId ? next(item) : item));
320	    } else {
321	      setAppointments(previous => [next, ...previous.filter(item => item.id !== next.id)]);
322	      setActiveAppointmentId(next.id);
323	    }
324	  };
325	  const openAppointment = (item: Appointment) => {
326	    setActiveAppointmentId(item.id);
327	    setIsDashboardOpen(true);
328	  };
329	  const [meetupPosts, setMeetupPosts] = useState<MeetupPost[]>(boot.data.posts);
330	  const [chatRooms, setChatRooms] = useState<ChatRoom[]>(boot.data.rooms);
331	  const [postAction, setPostAction] = useState<{ id: string; mode: 'closed' | 'deleted' } | null>(null);
332	  const [cancellationTarget, setCancellationTarget] = useState<{ id: string; kind: 'request' | 'appointment'; title: string } | null>(null);
333	  const [conflictPrompt, setConflictPrompt] = useState<{ conflicts: Appointment[]; action: ConflictAction } | null>(null);
334	  const [lifecycleNotice, setLifecycleNotice] = useState<string | null>(null);
335	  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);
336	  const [pendingRoomId, setPendingRoomId] = useState<string | null>(null);
337	  // Profiles are opened by user id and rebuilt on every render, so edits and saves show everywhere at once.
338	  const [selectedChatProfile, setSelectedChatProfile] = useState<ChatMember | null>(null);
339	  const [profileEditor, setProfileEditor] = useState<{ mode: 'setup' | 'edit'; step?: ProfileStep; reason?: string } | null>(null);
340	  const [isProfilePreviewOpen, setIsProfilePreviewOpen] = useState(false);
341	  const [safetyDialog, setSafetyDialog] = useState<{ kind: 'report' | 'block'; member: ChatMember } | null>(null);
342	  const matchingLocks = useRef(new Set<string>());
343	  const proposalLocks = useRef(new Set<string>());
344	  const activeRoom = chatRooms.find(room => room.id === activeRoomId && room.members.some(member => member.id === currentUser?.id));
345	  const activeRoomRequest = joinRequests.find(request => request.id === activeRoom?.requestId);
346	  const activeRoomPost = meetupPosts.find(post => post.id === activeRoom?.postId);
347	  const activeRoomAppointment = appointments.find(item => item.id === activeRoom?.appointmentId);
348	  const activePartner = activeRoom?.members.find(member => member.id !== currentUser?.id);
349	  const myAppointments = appointments.filter(item => currentUser && item.participantIds?.includes(currentUser.id));
350	  const openRoom = (room: ChatRoom) => {
351	    if (!roomAccess(room, currentUser?.id, joinRequests, appointments, meetupPosts, clock()).canView) return;
352	    setActiveRoomId(room.id);
353	    if (room.appointmentId) setActiveAppointmentId(room.appointmentId);
354	    setActiveTab('chat');
355	    setNotifications(prev => prev.map(item => item.roomId === room.id ? { ...item, read: true } : item));
356	  };
357	  const openRequestRoom = (id: string) => {
358	    const room = chatRooms.find(room => room.requestId === id);
359	    if (room) openRoom(room);
360	  };
361	  const openRequestProfile = (id: string) => {
362	    const room = chatRooms.find(room => room.requestId === id);
363	    if (!room || !roomAccess(room, currentUser?.id, joinRequests, appointments, meetupPosts, clock()).canView) return;
364	    const member = room.members.find(member => member.id !== currentUser?.id);
365	    if (member) setSelectedChatProfile(member);
366	  };
367	  const updateRoomDraft = (id: string, draft: string) => setChatRooms(prev => prev.map(room => room.id === id && room.members.some(member => member.id === currentUser?.id) ? { ...room, draft } : room));
368	  const sendRoomMessage = (id: string, text: string, sample = false) => {
369	    const room = chatRooms.find(room => room.id === id);
370	    if (!room || !text.trim() || !roomAccess(room, currentUser?.id, joinRequests, appointments, meetupPosts, clock()).canSend || (sample && currentUser?.id !== DEMO_USER_ID)) return;
371	    const senderId = sample ? room.members.find(member => member.id !== currentUser!.id)!.id : currentUser!.id;
372	    const message = { id: crypto.randomUUID(), senderId, text: text.trim(), createdAt: new Date().toISOString(), isSample: sample };
373	    setChatRooms(prev => prev.map(item => item.id === id ? { ...item, draft: sample ? item.draft : '', messages: [...item.messages, message] } : item));
374	    if (sample) setNotifications(prev => [{ id: `notif-${message.id}`, title: '새 동행 메시지 · 시연', description: text, roomId: id, type: 'chat', time: '방금', read: false }, ...prev]);
375	  };
376	  const proposeRoomSchedule = (id: string, proposal: ScheduleProposal) => {
377	    const room = chatRooms.find(room => room.id === id);
378	    const target = appointments.find(item => item.id === room?.appointmentId);
379	    if (!room || !target || target.status === '동행 완료' || !roomAccess(room, currentUser?.id, joinRequests, appointments, meetupPosts, clock()).canSend || !isValidMeetupRange(proposal.startsAt, proposal.endsAt)) return;
380	    if (room.messages.some(item => item.proposal?.status === 'pending')) { alert('먼저 보낸 일정 변경 제안의 응답을 기다려 주세요.'); return; }
381	    setChatRooms(prev => prev.map(item => item.id === id ? { ...item, messages: [...item.messages, { id: crypto.randomUUID(), senderId: currentUser!.id, text: '일정·장소 변경을 제안했어요.', createdAt: new Date().toISOString(), proposal }] } : item));
382	  };
383	  const resolveRoomProposal = (roomId: string, messageId: string, accepted: boolean, sample = false, ignoreConflict = false) => {
384	    const room = chatRooms.find(item => item.id === roomId);
385	    const message = room?.messages.find(item => item.id === messageId);
386	    const proposal = message?.proposal;
387	    const target = appointments.find(item => item.id === room?.appointmentId);
388	    if (!room || !target || target.status === '동행 완료' || !proposal || proposal.status !== 'pending' || proposalLocks.current.has(messageId) || !roomAccess(room, currentUser?.id, joinRequests, appointments, meetupPosts, clock()).canSend) return;
389	    if (sample ? currentUser?.id !== DEMO_USER_ID : message.senderId === currentUser?.id) return;
390	    if (accepted && !isValidMeetupRange(proposal.startsAt, proposal.endsAt)) return;
391	    if (accepted && !ignoreConflict && warnConflict({ kind: 'proposal', roomId, messageId, accepted, sample }, target.participantIds || [], proposal.startsAt, proposal.endsAt, target.id)) return;
392	    proposalLocks.current.add(messageId);
