1	import { appointmentStart, demoSchedule, koreaDateKey } from '../utils/calendar';
2	import React, { useState, useLayoutEffect } from 'react';
3	import { X, Calendar, MapPin, Lock, Info, Sparkles, ShieldCheck, AlertCircle } from 'lucide-react';
4	import { MeetupPost, CurrentUser } from '../types';
5	import { formatClock, formatMeetupRange, isValidMeetupRange } from '../utils/meetupLifecycle';
6	
7	interface CreateMeetupModalProps {
8	  isOpen: boolean;
9	  onClose: () => void;
10	  onCreateMeetup: (newPost: MeetupPost) => boolean;
11	  onUpdatePost?: (updatedPost: MeetupPost) => boolean;
12	  editPost?: MeetupPost | null;
13	  currentUser: CurrentUser | null;
14	}
15	
16	export const CreateMeetupModal: React.FC<CreateMeetupModalProps> = ({
17	  isOpen,
18	  onClose,
19	  onCreateMeetup,
20	  onUpdatePost,
21	  editPost,
22	  currentUser,
23	}) => {
24	  const [title, setTitle] = useState('');
25	  const [category, setCategory] = useState('식사');
26	  const [date, setDate] = useState(koreaDateKey(new Date(demoSchedule(1))));
27	  const [time, setTime] = useState('18:00');
28	  const [endDate, setEndDate] = useState(date);
29	  const [customDeadline, setCustomDeadline] = useState('');
30	  const [endTime, setEndTime] = useState('19:00');
31	  const [description, setDescription] = useState('');
32	  const [scheduleError, setScheduleError] = useState('');
33	  const [location, setLocation] = useState('서울 강남구 대치동');
34	  const [publicLocation, setPublicLocation] = useState('대치역 3번 출구 앞');
35	  const [secretLocation, setSecretLocation] = useState('르브런치 2층 예약석');
36	  const [partnerPreferences, setPartnerPreferences] = useState('시간 약속 잘 지키고 편안한 대화 나누실 분 환영해요 :)');
37	  const [tagInput, setTagInput] = useState('#맛집탐방 #주말브런치');
38	
39	  // Phase 6: Pro Paid Companion States
40	  const [companionType, setCompanionType] = useState<'free' | 'pro'>('free');
41	  const [showProRequirementModal, setShowProRequirementModal] = useState(false);
42	  const [hourlyRate, setHourlyRate] = useState<number>(25000);
43	  const [specialty, setSpecialty] = useState<string>('스냅 촬영 & 감성 보정');
44	  const [curriculum, setCurriculum] = useState<string>('10분: 촬영 컨셉 상담\n40분: 스냅 촬영\n10분: 사진 모니터링');
45	  const [included, setIncluded] = useState<string>('보정본 10장, 원본 전체');
46	  const [excluded, setExcluded] = useState<string>('카페 음료비 개인 부담');
47	
48	  const isEditing = Boolean(editPost);
49	
50	  const handleSelectProType = () => {
51	    // PRO 전문 동행 개설 조건: 당도 90 이상 및 본인인증 완료
52	    const isEligible = currentUser && currentUser.sugarContent >= 90 && currentUser.isPhoneVerified;
53	    if (!isEligible) {
54	      setShowProRequirementModal(true);
55	      return;
56	    }
57	    setCompanionType('pro');
58	  };
59	
60	  useLayoutEffect(() => {
61	    setScheduleError('');
62	    const cutoff = editPost?.recruitmentEndsAt;
63	    setCustomDeadline(cutoff && cutoff !== editPost?.startsAt ? `${koreaDateKey(new Date(cutoff))}T${formatClock(cutoff)}` : '');
64	    if (editPost) {
65	      setTitle(editPost.title);
66	      setCategory(editPost.category);
67	      setDescription(editPost.description || '');
68	      const start = appointmentStart({ scheduledAt: editPost.startsAt, dateTime: editPost.time });
69	      if (Number.isFinite(start.getTime())) {
70	        setDate(koreaDateKey(start));
71	        setTime(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Seoul', hour: '2-digit', minute: '2-digit' }).format(start));
72	      }
73	      const hasEnd = editPost.endsAt && Number.isFinite(Date.parse(editPost.endsAt));
74	      setEndDate(hasEnd ? koreaDateKey(new Date(editPost.endsAt!)) : '');
75	      setEndTime(hasEnd ? formatClock(editPost.endsAt!) : '');
76	      setLocation(editPost.location);
77	      setPublicLocation(editPost.publicLocation || '');
78	      setSecretLocation(editPost.secretLocation || '');
79	      setPartnerPreferences(editPost.partnerPreferences || '');
80	      setTagInput(editPost.tags.map((t) => `#${t}`).join(' '));
81	      setCompanionType(editPost.companionType || 'free');
82	      if (editPost.proDetails) {
83	        setHourlyRate(editPost.proDetails.hourlyRate);
84	        setSpecialty(editPost.proDetails.specialty);
85	        setCurriculum(editPost.proDetails.curriculum.join('\n'));
86	        setIncluded(editPost.proDetails.included.join(', '));
87	        setExcluded(editPost.proDetails.excluded.join(', '));
88	      }
89	    } else {
90	      setTitle('');
91	      setCategory('식사');
92	      setDate(koreaDateKey(new Date(demoSchedule(1))));
93	      setTime('18:00');
94	      setEndDate(koreaDateKey(new Date(demoSchedule(1))));
95	      setEndTime('19:00');
96	      setDescription('');
97	      setLocation('서울 강남구 대치동');
98	      setPublicLocation('대치역 3번 출구 앞');
99	      setSecretLocation('르브런치 2층 예약석');
100	      setPartnerPreferences('시간 약속 잘 지키고 편안한 대화 나누실 분 환영해요 :)');
101	      setTagInput('#맛집탐방 #주말브런치');
102	      setCompanionType('free');
103	      setHourlyRate(25000);
104	      setSpecialty('스냅 촬영 & 감성 보정');
105	      setCurriculum('10분: 촬영 컨셉 상담\n40분: 스냅 촬영\n10분: 사진 모니터링');
106	      setIncluded('보정본 10장, 원본 전체');
107	      setExcluded('카페 음료비 개인 부담');
108	    }
109	  }, [editPost, isOpen]);
110	
111	  if (!isOpen) return null;
112	
113	  const categories = ['전시', '축제', '식사', '운동', '여행', '클래스', '산책', '스터디', '공연', '쇼핑', '지금', '기타'];
114	
115	  const handleSubmit = (e: React.FormEvent) => {
116	    e.preventDefault();
117	    if (!title.trim()) return;
118	    const startValue = `${date}T${time}:00+09:00`;
119	    const endValue = `${endDate}T${endTime}:00+09:00`;
120	    if (!isValidMeetupRange(startValue, endValue)) {
121	      setScheduleError('종료 시각은 시작 시각보다 늦어야 해요. 다음 날 끝나면 종료 날짜도 바꿔 주세요.');
122	      return;
123	    }
124	    const deadline = new Date(`${customDeadline || `${date}T${time}`}:00+09:00`);
125	    if (!Number.isFinite(deadline.getTime()) || deadline.getTime() <= Date.now() || deadline.getTime() > Date.parse(startValue)) {
126	      setScheduleError('모집 마감은 현재 시각 이후, 동행 시작 시각 이전으로 정해 주세요. 시작 시각과 같게 설정할 수도 있어요.'); return;
127	    }
128	    const startsAt = new Date(startValue).toISOString();
129	    const endsAt = new Date(endValue).toISOString();
130	    const schedule = { startsAt, endsAt, recruitmentEndsAt: deadline.toISOString(), time: formatMeetupRange(startsAt, endsAt), description: description.trim() };
131	
132	    const parsedTags = tagInput
133	      ? tagInput
134	          .split(' ')
135	          .map((t) => t.replace('#', '').trim())
136	          .filter(Boolean)
137	      : [category, '1대1동행'];
138	
139	    if (companionType === 'pro') {
140	      if (!parsedTags.includes('PRO전문동행')) parsedTags.unshift('PRO전문동행');
141	    }
142	
143	    const proDetailsData = companionType === 'pro' ? {
144	      hourlyRate: Number(hourlyRate) || 25000,
145	      specialty: specialty.trim() || '맞춤 전문 동행',
146	      curriculum: curriculum.split('\n').map((s) => s.trim()).filter(Boolean),
147	      included: included.split(',').map((s) => s.trim()).filter(Boolean),
148	      excluded: excluded.split(',').map((s) => s.trim()).filter(Boolean),
149	    } : undefined;
150	
151	    if (isEditing && editPost && onUpdatePost) {
152	      const updated: MeetupPost = {
153	        ...editPost,
154	        title: title.trim(),
155	        category,
156	        ...schedule,
157	        location,
158	        publicLocation: publicLocation.trim(),
159	        secretLocation: secretLocation.trim(),
160	        partnerPreferences: partnerPreferences.trim(),
161	        tags: parsedTags,
162	        companionType,
163	        proDetails: proDetailsData,
164	      };
165	      if (!onUpdatePost(updated)) return;
166	    } else {
167	      const newPost: MeetupPost = {
168	        id: `post-${crypto.randomUUID()}`,
169	        category,
