570	                </div>
571	                <span className="text-[11px] font-bold text-gray-600 bg-gray-100 px-2 py-0.5 rounded">
572	                  3회 이상 권장
573	                </span>
574	              </div>
575	            </div>
576	
577	            <button
578	              type="button"
579	              onClick={() => {
580	                setShowProRequirementModal(false);
581	                setCompanionType('free');
582	              }}
583	              className="w-full py-3 bg-[#6c2cf5] hover:bg-[#5820d8] text-white font-bold rounded-xl text-sm transition-all shadow-md shadow-purple-500/20 active:scale-98"
584	            >
