2	import { ChevronRight, Inbox } from 'lucide-react';
3	import type { JoinRequest } from '../types';
4	import { ConditionReview } from './ConditionReview';
5	import { DEMO_USER_ID } from '../data/demoIdentity';
6	import { isOpenRequest } from '../utils/postLifecycle';
7	import { requestStatusLabel } from '../utils/conversations';
8	
9	export type RequestTab = 'sent' | 'received';
10	export interface CompanionRequestsProps {
11	  userId: string;
12	  requests: JoinRequest[];
13	  tab: RequestTab;
14	  onChangeTab: (tab: RequestTab) => void;
15	  onAccept: (requestId: string) => void;
16	  onReject: (requestId: string) => void;
17	  onOpenPost: (postId: string) => void;
18	  onOpenChat: (id: string) => void;
19	  onOpenProfile: (id: string) => void;
20	  onCancel: (id: string) => void;
21	  onReconfirm: (
22	    id: string,
23	    revision: number,
24	    agree: boolean,
25	    simulate?: boolean,
26	  ) => void;
27	}
28	export function CompanionRequests({
29	  userId,
30	  requests,
31	  tab,
32	  onChangeTab,
33	  onAccept,
34	  onReject,
35	  onOpenPost,
36	  onOpenChat,
37	  onOpenProfile,
38	  onCancel,
39	  onReconfirm,
40	}: CompanionRequestsProps) {
41	  const sent = requests.filter((r) => r.requesterId === userId);
42	  const received = requests.filter((r) => r.hostId === userId);
43	  const visible = tab === 'sent' ? sent : received;
44	  const labels = requestStatusLabel;
45	  return (
46	    <section
47	      aria-label="나의 동행 신청"
48	      className="bg-white px-5 pt-5 pb-6 border-b border-gray-100"
49	    >
50	      <h1 className="text-xl font-bold mb-4">나의 동행</h1>
51	      <div
52	        role="tablist"
53	        aria-label="동행 신청 구분"
54	        className="flex border-b border-gray-100 mb-4"
55	      >
56	        {(
57	          [
58	            ['sent', '신청한 동행', sent.length],
59	            ['received', '받은 신청', received.length],
60	          ] as const
61	        ).map(([value, label, count]) => (
62	          <button
63	            key={value}
64	            role="tab"
65	            aria-selected={tab === value}
66	            onClick={() => onChangeTab(value)}
67	            className={`flex-1 pb-3 text-sm font-bold border-b-2 ${tab === value ? 'border-[#6c2cf5] text-[#6c2cf5]' : 'border-transparent text-gray-400'}`}
68	          >
69	            {label} <span className="ml-1">{count}</span>
70	          </button>
71	        ))}
72	      </div>
73	      <div
74	        role="tabpanel"
75	        aria-label={tab === 'sent' ? '신청한 동행' : '받은 신청'}
76	        className="space-y-3"
77	      >
78	        {visible.length === 0 && (
79	          <div className="text-center py-8 text-gray-400">
80	            <Inbox className="mx-auto mb-3" />
81	            <p className="text-sm">
82	              {tab === 'sent'
83	                ? '아직 신청한 동행이 없어요.'
84	                : '아직 받은 신청이 없어요.'}
85	            </p>
86	          </div>
87	        )}
88	        {visible.map((request) => (
89	          <article
