92	            className="border border-gray-100 rounded-2xl p-4"
93	          >
94	            <div className="flex items-center justify-between mb-2">
95	              <span
96	                className={`text-[11px] px-2 py-1 rounded-full font-bold ${request.status === 'accepted' ? 'text-green-700 bg-green-50' : isOpenRequest(request) ? 'text-[#6c2cf5] bg-purple-50' : 'text-gray-500 bg-gray-100'}`}
97	              >
98	                {labels[request.status]}
99	              </span>
100	              <span className="text-[11px] text-gray-400">
101	                {request.createdAt}
102	              </span>
103	            </div>
104	            <button
105	              onClick={() => onOpenPost(request.postId)}
106	              className="flex w-full items-center justify-between gap-2 text-left font-bold text-sm leading-relaxed"
107	            >
108	              {request.postTitle}
109	              <ChevronRight size={16} className="shrink-0 text-gray-400" />
110	            </button>
111	            {tab === 'received' && (
112	              <button
113	                onClick={() => onOpenProfile(request.id)}
114	                aria-label={`${request.requesterName}님의 상세 프로필 보기`}
