127	                </span>
128	                <span className="ml-auto text-[11px] text-[#6c2cf5]">
129	                  프로필 보기 →
130	                </span>
131	              </button>
132	            )}
133	            <p className="text-xs leading-relaxed text-gray-500 mt-3">
134	              {request.message}
