141	            <ConditionReview
142	              request={request}
143	              userId={userId}
144	              onRespond={(revision, agree) =>
145	                onReconfirm(request.id, revision, agree)
146	              }
147	              onSimulate={
148	                userId === DEMO_USER_ID && request.hostId === userId
149	                  ? (revision, agree) =>
150	                      onReconfirm(request.id, revision, agree, true)
151	                  : undefined
152	              }
153	            />
154	            <button
155	              onClick={() => onOpenChat(request.id)}
156	              className="w-full mt-3 bg-purple-50 text-[#6c2cf5] py-2.5 rounded-xl text-xs font-bold"
157	            >
158	              {isOpenRequest(request) ? '대화하기' : '대화 내역 보기'}
159	            </button>
160	            {tab === 'sent' && isOpenRequest(request) && (
161	              <button
162	                onClick={() => onCancel(request.id)}
163	                className="text-xs text-gray-500 underline mt-3"
164	              >
165	                신청 취소
166	              </button>
167	            )}
168	            {tab === 'received' && isOpenRequest(request) && (
169	              <div className="flex gap-2 mt-4">
170	                <button
171	                  onClick={() => onReject(request.id)}
172	                  className="flex-1 bg-gray-100 text-gray-500 py-2.5 rounded-xl text-xs font-semibold"
173	                >
174	                  거절
175	                </button>
176	                <button
177	                  disabled={request.status === 'reconfirming'}
178	                  onClick={() => onAccept(request.id)}
179	                  className="flex-1 bg-[#6c2cf5] text-white py-2.5 rounded-xl text-xs font-bold disabled:bg-gray-200 disabled:text-gray-500"
180	                >
181	                  {request.status === 'reconfirming'
182	                    ? '조건 동의 대기'
183	                    : '수락하기'}
184	                </button>
185	              </div>
186	            )}
187	          </article>
188	        ))}
189	      </div>
190	    </section>
191	  );
192	}
