46	      <div className="w-full max-w-[440px] h-full bg-[#f7f8fc] flex flex-col relative shadow-2xl overflow-hidden">
47	        {/* Top Minimal Header (실선 제거 및 부드러운 블러) */}
48	        <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-xl px-4 py-3.5 flex items-center justify-between">
49	          <div className="flex items-center gap-2">
50	            <button
51	              onClick={onClose}
52	              className="p-1.5 -ml-1 rounded-full text-gray-800 hover:text-black hover:bg-gray-100/70 active:scale-95 transition-all"
53	              aria-label="뒤로가기"
54	            >
55	              <ChevronLeft className="w-6 h-6 stroke-[2.2]" />
56	            </button>
57	            <div className="flex items-center gap-2">
58	              <div className={`w-7 h-7 rounded-xl ${category.iconBg} flex items-center justify-center shadow-2xs`}>
59	                <CategoryIcon type={category.iconType} className="w-4 h-4" />
60	              </div>
61	              <h2 className="text-[17px] font-extrabold text-gray-900 tracking-tight">
62	                {category.iconType === 'flash' ? '지금이당!' : `${category.name} 동행`}
63	              </h2>
64	            </div>
65	          </div>
66	
67	          <button
68	            onClick={() => {
69	              onClose();
70	              onOpenCreate();
71	            }}
72	            className="px-3 py-1.5 bg-[#6c2cf5] text-white text-xs font-bold rounded-full hover:bg-[#5820d8] active:scale-95 transition-all shadow-xs flex items-center gap-1"
73	          >
74	            <Plus className="w-3.5 h-3.5 stroke-[2.5]" />
75	            <span>모집하기</span>
76	          </button>
77	        </header>
78	
79	        {/* Scrollable Page Body */}
80	        <div className="flex-1 overflow-y-auto pb-28">
81	          {/* Top Category Info & Search Area (실선 없이 순백색 면 분할) */}
82	          <div className="bg-white px-5 pt-3 pb-5 rounded-b-[28px] shadow-[0_4px_20px_rgba(0,0,0,0.02)] space-y-4">
