3	const DAY = 86_400_000;
4	export function koreaDateParts(now = new Date()) {
5	  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Seoul', year: 'numeric', month: 'numeric', day: 'numeric' }).formatToParts(now);
6	  const part = (type: string) => Number(parts.find(p => p.type === type)!.value);
7	  return { year: part('year'), month: part('month'), day: part('day') };
8	}
9	export const dateKey = (year: number, month: number, day: number) => `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
10	export function koreaDateKey(now = new Date()) {
11	  const { year, month, day } = koreaDateParts(now);
12	  return dateKey(year, month, day);
13	}
14	export const weekOfMonth = (day: number) => Math.ceil(day / 7);
15	export const daysInMonth = (year: number, month: number) => new Date(Date.UTC(year, month, 0)).getUTCDate();
16	export const weeksInMonth = (year: number, month: number) => weekOfMonth(daysInMonth(year, month));
17	export function eventsStartingInWeek(events: EventBannerItem[], year: number, month: number, week: number) {
18	  return events.filter(event => {
19	    const [y, m, d] = event.startsOn.split('-').map(Number);
20	    return y === year && m === month && weekOfMonth(d) === week;
21	  }).sort((a, b) => a.startsOn.localeCompare(b.startsOn));
