                  </button>

                  {canEdit ? (
                    <button
                      onClick={() => onClosePost(post.id)}
                      className="py-3 bg-amber-100/70 hover:bg-amber-100 text-amber-800 rounded-xl text-xs font-bold flex items-center justify-center gap-1.5 transition-colors"
