 * The one public view of a user for every screen (post, request, chat, appointment).
 * Phone, real name, birth date, email and referral code are never copied into it.
 */
export function publicProfileOf(member: ChatMember, directory: Record<string, CurrentUser>): PublicUserProfile {
  const base: PublicUserProfile = {
    id: member.id, displayName: member.displayName, avatar: member.avatar,
    bio: '', neighborhood: '', ageGroup: '', hobbies: [], traits: [], sugarContent: null,
    isPhoneVerified: false, isKycVerified: false, isSample: false, reviews: [],
  };
  const account = directory[member.id];
  if (account) return {
    ...base, displayName: account.maskedName, avatar: avatarSrc(account.avatar), bio: account.bio,
    // Only the age band derived from the birth date is public, never the date itself.
    neighborhood: account.neighborhood, ageGroup: ageGroupOf(account.birthDate) || account.ageGroup,
    hobbies: account.hobbies || [], traits: account.traits || [],
    sugarContent: Number.isFinite(account.sugarContent) ? account.sugarContent : NEW_USER_SUGAR,
    isPhoneVerified: account.isPhoneVerified, isKycVerified: account.isKycVerified,
    isSample: Boolean(account.isSample) || account.id === DEMO_USER_ID,
    reviews: account.isSample && account.id !== DEMO_USER_ID && sampleProfiles[account.id] ? sampleReviews(account.id) : [],
  };
  const sample = sampleProfiles[member.id];
  if (!sample) return base;
  return { ...base, ...sample, isSample: true, isPhoneVerified: true, reviews: sampleReviews(member.id) };
}

export function publicProfileForMember(member: ChatMember, currentUser: CurrentUser | null, users: CurrentUser[] = []): PublicUserProfile {
  return publicProfileOf(member, userDirectory(users, currentUser));
}

export function publicProfileForPost(post: MeetupPost, currentUser: CurrentUser | null, users: CurrentUser[] = []): PublicUserProfile {
  return publicProfileForMember({ id: post.authorId || `unknown-${post.id}`, displayName: post.author, avatar: post.avatar }, currentUser, users);
}
import type { Appointment, CompletionConfirmation, FavoriteFriend, NotificationSettings } from '../types.ts';

/** A real past meetup: completed, or both participants confirmed completion. */
export function hasMetBefore(
  userId: string,
  otherId: string,
  appointments: Appointment[],
  completions: CompletionConfirmation[] = [],
) {
  return appointments.some(item => {
    if (!item.participantIds?.includes(userId) || !item.participantIds.includes(otherId)) return false;
    if (item.status === '동행 완료') return true;
    const confirmed = new Set(completions.filter(entry => entry.appointmentId === item.id).map(entry => entry.userId));
    return confirmed.has(userId) && confirmed.has(otherId);
  });
}

export const isSavedBy = (ownerId: string, targetId: string, favorites: FavoriteFriend[]) =>
  favorites.some(item => item.ownerId === ownerId && item.targetId === targetId);

/** Always judged from the recipient's side. A stranger is not saved AND not met. */
export function relationToSender(
  recipientId: string,
  senderId: string,
  favorites: FavoriteFriend[],
  appointments: Appointment[],
  completions: CompletionConfirmation[] = [],
) {
  const isFavorite = isSavedBy(recipientId, senderId, favorites);
  const metBefore = hasMetBefore(recipientId, senderId, appointments, completions);
  return { isFavorite, hasMetBefore: metBefore, isStranger: !isFavorite && !metBefore };
}

export const defaultNotificationSettings = (userId: string): NotificationSettings => ({ userId, strangerInvitations: true });

export const notificationSettingsFor = (settings: NotificationSettings[], userId: string) =>
  settings.find(item => item.userId === userId) || defaultNotificationSettings(userId);
import type { Appointment, CurrentUser, NotificationItem } from '../types.ts';

/** Conversations, appointments and settings are private; public posts are not. */
export const canUsePrivateArea = (user: Pick<CurrentUser, 'isLoggedIn'> | null | undefined) =>
  Boolean(user?.isLoggedIn);

/** Only participants of a confirmed or completed meetup see the detailed place. Closing a post reveals nothing. */
export function canViewSecretLocation(postId: string | undefined, appointments: Appointment[], userId: string | undefined) {
  if (!postId || !userId) return false;
  return appointments.some(item =>
    item.postId === postId &&
    item.participantIds?.includes(userId) &&
    ['매칭 확정', '매칭완료', '동행 완료'].includes(item.status),
  );
}

/** Addressed notifications are shown only to their recipient. Untargeted legacy items keep the old behavior. */
export const visibleNotifications = (items: NotificationItem[], userId: string | undefined) =>
  items.filter(item => !item.recipientId || item.recipientId === userId);
