export const DEADLINE_MESSAGE = '모집 마감은 현재 시각 이후, 동행 시작 시각 이전으로 정해 주세요. 시작 시각과 같게 설정할 수도 있어요.';

const DAY = 86_400_000;
const koreaMs = (date: string, time: string) =>
