  return {
    title: '', category, description: '',
    startDate: day, startTime: '18:00', endDate: day, endTime: '19:00', deadline: '',
    location: '서울 강남구 대치동', publicLocation: '대치역 3번 출구 앞', secretLocation: '르브런치 2층 예약석',
