              <span className="bg-[#ff5d2b] text-white text-xs font-bold px-2.5 py-1 rounded-[8px] shadow-sm">
                {event.badge}
              </span>
              <span className="bg-white/90 backdrop-blur-xs text-gray-900 text-xs font-bold px-2.5 py-1 rounded-[8px]">
                {event.tag}
