  const open: LifecycleState = { posts: [post()], requests: [request('r1', 'a')], rooms: [], appointments: [], notifications: [] };
  const closed = closePost(open, 'p1', 'closed', 'host', now)!;
  assert.equal(closed.requests[0].status, 'post_closed');
